"""Marges de craft, directes et récursives."""
import sqlite3
from dataclasses import dataclass, field

from .prices import Liquidity, PriceBook, PriceRef

BUY = "achat"
CRAFT = "craft"


@dataclass(frozen=True, slots=True)
class Item:
    id: int
    name: str
    level: int
    exchangeable: bool


@dataclass(frozen=True, slots=True)
class Recipe:
    result_id: int
    job_id: int
    level: int
    ingredients: tuple[tuple[int, int], ...]  # (item, quantité)


@dataclass(frozen=True, slots=True)
class UnitCost:
    """Coût le plus bas pour obtenir une unité d'un item. cost est None si aucun moyen n'a de prix."""

    cost: float | None
    mode: str | None = None
    missing: frozenset[int] = frozenset()  # items sans prix qui empêchent le calcul


@dataclass(slots=True)
class CraftResult:
    recipe: Recipe
    item: Item
    job: str
    sell: PriceRef | None
    revenue: float | None  # prix de vente net de taxe
    direct_cost: float | None  # tous les ingrédients achetés
    recursive_cost: float | None  # min(achat, craft) à chaque niveau
    liquidity: Liquidity
    low_liquidity: bool
    missing_prices: list[int] = field(default_factory=list)
    non_exchangeable_ingredients: list[int] = field(default_factory=list)
    crafted_ingredients: list[int] = field(default_factory=list)  # sous-crafts retenus par le calcul récursif
    result_not_exchangeable: bool = False
    own_job: bool | None = None  # réalisable avec tes métiers ; None si aucun métier n'est configuré
    weighted_margin: float | None = None

    @property
    def margin(self) -> float | None:
        if self.revenue is None or self.direct_cost is None:
            return None
        return self.revenue - self.direct_cost

    @property
    def recursive_margin(self) -> float | None:
        if self.revenue is None or self.recursive_cost is None:
            return None
        return self.revenue - self.recursive_cost

    @property
    def margin_pct(self) -> float | None:
        """Marge récursive rapportée au capital engagé."""
        margin = self.recursive_margin
        if margin is None or not self.recursive_cost:
            return None
        return margin / self.recursive_cost

    @property
    def flags(self) -> list[str]:
        out = []
        if self.result_not_exchangeable:
            out.append("résultat non échangeable")
        if self.missing_prices:
            out.append(f"{len(self.missing_prices)} prix manquant(s)")
        if self.non_exchangeable_ingredients:
            out.append("ingrédient non échangeable")
        if not self.liquidity.known:
            out.append("liquidité inconnue")
        elif self.low_liquidity:
            out.append("peu échangé")
        return out


def load_items(conn: sqlite3.Connection) -> dict[int, Item]:
    return {
        i: Item(i, name, level, bool(exchangeable))
        for i, name, level, exchangeable in conn.execute("SELECT id, name, level, exchangeable FROM items")
    }


def load_recipes(conn: sqlite3.Connection) -> dict[int, Recipe]:
    ingredients: dict[int, list[tuple[int, int]]] = {}
    for result_id, item_id, quantity in conn.execute("SELECT result_id, item_id, quantity FROM recipe_ingredients"):
        ingredients.setdefault(result_id, []).append((item_id, quantity))
    return {
        result_id: Recipe(result_id, job_id, level, tuple(ingredients.get(result_id, ())))
        for result_id, job_id, level in conn.execute("SELECT result_id, job_id, level FROM recipes")
    }


def resolve_jobs(conn: sqlite3.Connection, jobs: dict[str, int]) -> tuple[dict[int, int], list[str]]:
    """Convertit {nom de métier: niveau} en {id: niveau}. Renvoie aussi les noms inconnus."""
    by_name = {name.casefold(): job_id for job_id, name in conn.execute("SELECT id, name FROM jobs")}
    resolved, unknown = {}, []
    for name, level in jobs.items():
        job_id = by_name.get(name.casefold())
        if job_id is None:
            unknown.append(name)
        else:
            resolved[job_id] = level
    return resolved, unknown


class CraftCalculator:
    def __init__(
        self,
        items: dict[int, Item],
        recipes: dict[int, Recipe],
        prices: PriceBook,
        hdv_tax: float,
        job_levels: dict[int, int] | None = None,
        min_liquidity: int = 0,
    ) -> None:
        """job_levels : {id de métier: niveau} du joueur, ou None s'il n'en a pas configuré.

        Les métiers ne restreignent jamais le calcul : un craft peut être confié à un autre
        joueur. Ils servent seulement à marquer et filtrer ce que le joueur peut faire lui-même.
        """
        self.items = items
        self.recipes = recipes
        self.prices = prices
        self.tax = hdv_tax
        self.job_levels = job_levels
        self.min_liquidity = min_liquidity
        self._memo: dict[int, UnitCost] = {}

    def own_job(self, recipe: Recipe) -> bool | None:
        if self.job_levels is None:
            return None
        return self.job_levels.get(recipe.job_id, 0) >= recipe.level

    def _buy_price(self, item_id: int) -> int | None:
        item = self.items.get(item_id)
        if item is None or not item.exchangeable:
            return None
        ref = self.prices.get(item_id)
        return ref.price if ref is not None else None

    def unit_cost(self, item_id: int) -> UnitCost:
        return self._unit_cost(item_id, set())[0]

    def _unit_cost(self, item_id: int, stack: set[int]) -> tuple[UnitCost, bool]:
        """Renvoie (coût, dépend d'un cycle). Un résultat obtenu en coupant un cycle n'est pas mémorisé."""
        if item_id in self._memo:
            return self._memo[item_id], False
        buy = self._buy_price(item_id)
        recipe = self.recipes.get(item_id)
        craft: float | None = None
        missing: set[int] = set()
        tainted = False
        if recipe is not None and recipe.ingredients:
            if item_id in stack:
                tainted = True  # garde anti-cycle : dans cette branche, l'item ne peut qu'être acheté
            else:
                stack.add(item_id)
                craft = 0.0
                for ingredient_id, quantity in recipe.ingredients:
                    sub, sub_tainted = self._unit_cost(ingredient_id, stack)
                    tainted = tainted or sub_tainted
                    if sub.cost is None:
                        missing |= sub.missing or {ingredient_id}
                        craft = None
                    elif craft is not None:
                        craft += quantity * sub.cost
                stack.discard(item_id)
        if buy is not None and (craft is None or buy <= craft):
            result = UnitCost(float(buy), BUY)
        elif craft is not None:
            result = UnitCost(craft, CRAFT)
        else:
            result = UnitCost(None, None, frozenset(missing or {item_id}))
        if not tainted:
            self._memo[item_id] = result
        return result, tainted

    def evaluate(self, recipe: Recipe, job_name: str = "") -> CraftResult:
        item = self.items[recipe.result_id]
        sell = self.prices.get(recipe.result_id) if item.exchangeable else None
        liquidity = self.prices.liquidity(recipe.result_id)
        low = liquidity.qty_7d is not None and liquidity.qty_7d < self.min_liquidity
        result = CraftResult(
            recipe=recipe,
            item=item,
            job=job_name,
            sell=sell,
            revenue=sell.price * (1 - self.tax) if sell is not None else None,
            direct_cost=0.0,
            recursive_cost=0.0,
            liquidity=liquidity,
            low_liquidity=low,
            result_not_exchangeable=not item.exchangeable,
            own_job=self.own_job(recipe),
        )
        if item.exchangeable and sell is None:
            result.missing_prices.append(item.id)
        for ingredient_id, quantity in recipe.ingredients:
            ingredient = self.items.get(ingredient_id)
            if ingredient is not None and not ingredient.exchangeable:
                result.non_exchangeable_ingredients.append(ingredient_id)
            buy = self._buy_price(ingredient_id)
            if buy is None:
                result.direct_cost = None
            elif result.direct_cost is not None:
                result.direct_cost += quantity * buy
            unit = self.unit_cost(ingredient_id)
            if unit.cost is None:
                result.recursive_cost = None
                result.missing_prices += sorted(unit.missing - set(result.missing_prices))
            else:
                if unit.mode == CRAFT:
                    result.crafted_ingredients.append(ingredient_id)
                if result.recursive_cost is not None:
                    result.recursive_cost += quantity * unit.cost
        margin = result.recursive_margin
        if margin is not None:
            # Un objet sous le seuil de liquidité voit sa marge réduite au prorata ; liquidité inconnue = pas de pénalité.
            factor = 1.0
            if low and self.min_liquidity > 0:
                factor = (liquidity.qty_7d or 0) / self.min_liquidity
            result.weighted_margin = margin * factor
        return result


def rank_crafts(conn: sqlite3.Connection, calculator: CraftCalculator) -> list[CraftResult]:
    """Évalue toutes les recettes. Les recettes incalculables sont gardées, en fin de classement."""
    job_names = dict(conn.execute("SELECT id, name FROM jobs"))
    results = [
        calculator.evaluate(recipe, job_names.get(recipe.job_id, f"#{recipe.job_id}"))
        for recipe in calculator.recipes.values()
    ]
    results.sort(key=lambda r: (r.weighted_margin is None, -(r.weighted_margin or 0.0), r.item.name))
    return results

"""Serveur HTTP local de l'interface. Bibliothèque standard uniquement.

N'écoute que sur 127.0.0.1 : l'interface n'est pas accessible depuis le réseau.
"""
import json
import logging
import mimetypes
import re
import socket
import urllib.error
import urllib.request
from http import HTTPStatus
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import parse_qs, urlparse

from .. import db
from .api import Api

log = logging.getLogger("dofustool.web")

STATIC_DIR = Path(__file__).resolve().parent / "static"
ICON_DIR = db.MARKET_PATH.parent / "icons"
ICON_URL = "https://api.dofusdb.fr/img/items/{icon_id}.png"
EFFECT_ICON_URL = "https://dofusdb.fr/icons/characteristics/{asset}.png"
# Images que DofusDB range sous un autre nom que celui des données du jeu (vérifié le 05/10/2026).
EFFECT_ICON_ALIASES = {
    "tx_strengthRes": "tx_res_strength",
    "tx_agilityRes": "tx_res_agility",
    "tx_chanceRes": "tx_res_chance",
    "tx_intelligenceRes": "tx_res_intelligence",
    "tx_neutralRes": "tx_res_neutral",
    "tx_resMelee": "tx_res_melee",
    "tx_distanceRes": "tx_res_distance",
    "tx_weaponRes": "tx_res_weapon",
    "tx_spellsRes": "tx_res_spell",
    "tx_damageMelee": "tx_meleeDamage",
    "tx_distance": "tx_distanceDamage",
    "tx_spells": "tx_spellDamage",
    "tx_weapon": "tx_weaponDamage",
}
DEFAULT_PORT = 8600


# Effets sans caractéristique, dont le jeu montre pourtant une icône (le couteau rouge d'« Arme de chasse »).
OTHER_EFFECT_ICONS = {"armeChasse": "https://dofusdb.fr/icons/effects/armeChasse.png"}


def fetch_effect_icon(asset: str, directory: Path = ICON_DIR) -> bytes | None:
    """Image d'une caractéristique (vitalité, force…), avec le même cache que les images d'items."""
    remote = EFFECT_ICON_ALIASES.get(asset, asset)
    url = OTHER_EFFECT_ICONS.get(asset) or EFFECT_ICON_URL.format(asset=remote)
    return fetch_icon(asset, directory / "effects", url)


def fetch_icon(icon_id: int | str, directory: Path = ICON_DIR, url: str | None = None) -> bytes | None:
    """Image d'un item : lue dans le cache local, sinon téléchargée une fois sur DofusDB."""
    path = directory / f"{icon_id}.png"
    if path.exists():
        return path.read_bytes()
    try:
        request = urllib.request.Request(url or ICON_URL.format(icon_id=icon_id), headers={"User-Agent": "dofustool"})
        with urllib.request.urlopen(request, timeout=10) as response:
            content = response.read()
    except (urllib.error.URLError, TimeoutError, OSError):
        return None
    if not content.startswith(b"\x89PNG"):
        return None
    directory.mkdir(parents=True, exist_ok=True)
    path.write_bytes(content)
    return content


def make_handler(api: Api, icon_dir: Path = ICON_DIR) -> type[BaseHTTPRequestHandler]:
    def to_int(text: str | None) -> int | None:
        return int(text) if text and text.lstrip("-").isdigit() else None

    class Handler(BaseHTTPRequestHandler):
        server_version = "dofustool"

        def log_message(self, format: str, *args) -> None:  # noqa: A002
            pass  # pas de journal par requête

        def _send(self, status: int, body: bytes, content_type: str, cache: str = "no-store") -> None:
            self.send_response(status)
            self.send_header("Content-Type", content_type)
            self.send_header("Content-Length", str(len(body)))
            self.send_header("Cache-Control", cache)
            self.end_headers()
            self.wfile.write(body)

        def _json(self, payload, status: int = HTTPStatus.OK) -> None:
            body = json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
            self._send(status, body, "application/json; charset=utf-8")

        def _not_found(self) -> None:
            self._json({"error": "introuvable"}, HTTPStatus.NOT_FOUND)

        def do_GET(self) -> None:  # noqa: N802
            url = urlparse(self.path)
            query = {k: v[0] for k, v in parse_qs(url.query).items()}
            path = url.path
            try:
                if path == "/api/version":
                    return self._json(api.version())
                if path == "/api/status":
                    return self._json(api.status())
                if path == "/api/crafts":
                    return self._json(api.crafts())
                if path == "/api/trends":
                    return self._json(api.trends())
                if path == "/api/config":
                    return self._json(api.config())
                if path == "/api/launcher":
                    return self._json(api.find_launcher(query.get("current", "")))
                if path == "/api/jobs":
                    return self._json(api.jobs())
                if path == "/api/breeding":
                    return self._json(api.breeding())
                if path == "/api/jobs/plan":
                    exclude = frozenset(int(x) for x in query.get("exclude", "").split(",") if x.isdigit())
                    try:
                        bonus = float(query.get("bonus", "100"))
                    except ValueError:
                        bonus = 100.0
                    return self._json(
                        api.job_plan(
                            to_int(query.get("job")) or 0,
                            max(0, to_int(query.get("xp")) or 0),
                            to_int(query.get("target")) or 1,
                            min(1000.0, max(0.0, bonus)),
                            query.get("resale") == "1",
                            exclude,
                            min(100.0, max(5.0, float(to_int(query.get("rate")) or 77))) / 100,
                            query.get("heavy") == "1",
                        )
                    )
                if path == "/api/ignored":
                    return self._json(api.ignored())
                if path == "/api/workshop":
                    return self._json(api.workshop())
                if path == "/api/ganymede":
                    return self._json(api.ganymede_guides())
                if path == "/api/today":
                    try:
                        since = float(query["since"]) if "since" in query else None
                    except ValueError:
                        since = None
                    return self._json(api.today(since))
                if path == "/api/almanax":
                    return self._json(api.almanax(query.get("day")))
                if path == "/api/sales":
                    return self._json(api.sales())
                if path == "/api/stock":
                    return self._json(api.stock())
                if path == "/api/stock/crafts":
                    return self._json(api.stock_crafts())
                if path == "/api/items":
                    return self._json(api.items())
                if match := re.fullmatch(r"/api/item/(\d+)/tip", path):
                    payload = api.item_tip(int(match[1]))
                    return self._json(payload) if payload else self._not_found()
                if match := re.fullmatch(r"/api/item/(\d+)", path):
                    payload = api.item(int(match[1]))
                    return self._json(payload) if payload else self._not_found()
                if path == "/api/forge/options":
                    return self._json(api.forge_options())
                if match := re.fullmatch(r"/api/forge/item/(\d+)", path):
                    payload = api.forge_item(int(match[1]))
                    return self._json(payload) if payload else self._not_found()
                if path == "/api/forge/journal":
                    return self._json(api.forge_journal())
                if path == "/api/forge/collecte":
                    return self._json(api.forge_collecte())
                if match := re.fullmatch(r"/api/forge/collecte/([a-z0-9-]{1,40})", path):
                    payload = api.forge_collecte_items(match[1])
                    return self._json(payload) if payload else self._not_found()
                if path == "/api/forge/ranking":
                    return self._json(
                        api.forge_ranking(
                            query.get("criterion", "saved"),
                            to_int(query.get("exo")),
                            to_int(query.get("effect")),
                            to_int(query.get("amount")),
                            to_int(query.get("exo_value")),
                            query.get("exact") == "1",
                            {"1": True, "0": False}.get(query.get("hunting", "")),
                        )
                    )
                if match := re.fullmatch(r"/icons/effects/([A-Za-z0-9_]{1,64})\.png", path):
                    content = fetch_effect_icon(match[1], icon_dir)
                    if content is None:
                        return self._not_found()
                    return self._send(HTTPStatus.OK, content, "image/png", "max-age=604800")
                if match := re.fullmatch(r"/icons/(\d+)\.png", path):
                    content = fetch_icon(int(match[1]), icon_dir)
                    if content is None:
                        return self._not_found()
                    return self._send(HTTPStatus.OK, content, "image/png", "max-age=604800")
                return self._static(path)
            except Exception:  # une erreur de calcul ne doit pas faire tomber le serveur
                log.exception("Erreur sur %s", path)
                self._json({"error": "erreur interne, voir la console du serveur"}, HTTPStatus.INTERNAL_SERVER_ERROR)

        def _local_request(self) -> bool:
            """Vrai si la requête vient bien de l'interface elle-même, pas d'une page d'un autre site."""
            host = (self.headers.get("Host") or "").rsplit(":", 1)[0]
            origin = self.headers.get("Origin")
            json_body = (self.headers.get("Content-Type") or "").split(";")[0].strip() == "application/json"
            return (
                host in ("localhost", "127.0.0.1")
                and json_body
                and (origin is None or urlparse(origin).hostname in ("localhost", "127.0.0.1"))
            )

        def do_POST(self) -> None:  # noqa: N802
            path = urlparse(self.path).path
            if not self._local_request():
                # Lire le corps avant de répondre : sinon la connexion est coupée sous les pieds du client.
                self.rfile.read(min(int(self.headers.get("Content-Length") or 0), 65536))
                return self._json({"error": "requête refusée"}, HTTPStatus.FORBIDDEN)
            try:
                if path == "/api/equipment-price":
                    length = min(int(self.headers.get("Content-Length") or 0), 4096)
                    payload = json.loads(self.rfile.read(length) or b"{}")
                    if not isinstance(payload, dict) or not isinstance(payload.get("mode"), str):
                        raise ValueError("mode attendu")
                    return self._json(api.set_equipment_price(payload["mode"]))
                if path == "/api/config":
                    length = min(int(self.headers.get("Content-Length") or 0), 65536)
                    payload = json.loads(self.rfile.read(length) or b"{}")
                    if not isinstance(payload, dict):
                        raise ValueError("objet JSON attendu")
                    return self._json(api.save_config(payload))
                if match := re.fullmatch(r"/api/forge/item/(\d+)/filter", path):
                    length = min(int(self.headers.get("Content-Length") or 0), 65536)
                    payload = json.loads(self.rfile.read(length) or b"{}")
                    if not isinstance(payload, dict):
                        raise ValueError("objet JSON attendu")
                    return self._json(api.save_forge_filter(int(match[1]), payload))
                if path == "/api/forge/journal/base":
                    length = min(int(self.headers.get("Content-Length") or 0), 4096)
                    payload = json.loads(self.rfile.read(length) or b"{}")
                    cost = payload.get("cost") if isinstance(payload, dict) else None
                    if not isinstance(payload, dict) or not isinstance(payload.get("uid"), int):
                        raise ValueError("uid attendu")
                    if cost is not None and (not isinstance(cost, int) or isinstance(cost, bool) or not 0 <= cost <= 10**12):
                        raise ValueError("prix invalide")
                    return self._json(api.set_forge_base_cost(payload["uid"], cost))
                if path == "/api/workshop":
                    length = min(int(self.headers.get("Content-Length") or 0), 65536)
                    payload = json.loads(self.rfile.read(length) or b"{}")
                    if not isinstance(payload, dict):
                        raise ValueError("objet JSON attendu")
                    return self._json(api.workshop_action(payload))
                if path == "/api/ignore-type":
                    length = min(int(self.headers.get("Content-Length") or 0), 4096)
                    payload = json.loads(self.rfile.read(length) or b"{}")
                    if not isinstance(payload, dict) or not isinstance(payload.get("type"), str):
                        raise ValueError("type attendu")
                    return self._json(api.set_type_ignored(payload["type"], bool(payload.get("ignored", True))))
                if path == "/api/ignore":
                    length = min(int(self.headers.get("Content-Length") or 0), 4096)
                    payload = json.loads(self.rfile.read(length) or b"{}")
                    if not isinstance(payload, dict) or not isinstance(payload.get("item_id"), int):
                        raise ValueError("item_id attendu")
                    return self._json(api.set_ignored(payload["item_id"], bool(payload.get("ignored", True))))
                self._not_found()
            except (ValueError, TypeError) as exc:
                self._json({"error": f"requête invalide : {exc}"}, HTTPStatus.BAD_REQUEST)
            except Exception:
                log.exception("Erreur sur %s", path)
                self._json({"error": "erreur interne"}, HTTPStatus.INTERNAL_SERVER_ERROR)

        def _static(self, path: str) -> None:
            name = "index.html" if path in ("/", "") else path.lstrip("/")
            target = (STATIC_DIR / name).resolve()
            if STATIC_DIR not in target.parents or not target.is_file():
                return self._not_found()
            content_type = mimetypes.guess_type(target.name)[0] or "application/octet-stream"
            if content_type.startswith("text/") or content_type.endswith(("javascript", "json")):
                content_type += "; charset=utf-8"
            self._send(HTTPStatus.OK, target.read_bytes(), content_type)

    return Handler


def serve(port: int = DEFAULT_PORT, db_path: Path | str = db.MARKET_PATH) -> ThreadingHTTPServer:
    api = Api(db_path)
    server = ThreadingHTTPServer(("127.0.0.1", port), make_handler(api))
    server.api = api  # pour la préparation en arrière-plan (warm)
    return server


class _LocalIPv6Server(ThreadingHTTPServer):
    address_family = socket.AF_INET6


def serve_ipv6(api: Api, port: int) -> ThreadingHTTPServer | None:
    """La même interface sur l'adresse IPv6 de ce PC (::1), toujours inaccessible depuis le réseau.

    Windows essaie « localhost » d'abord en IPv6 : sans cette écoute, chaque demande du navigateur attendait
    deux secondes avant de se rabattre sur l'IPv4. None si l'IPv6 n'est pas disponible."""
    try:
        return _LocalIPv6Server(("::1", port), make_handler(api))
    except OSError:
        return None


def warm(api: Api) -> None:
    """Prépare en arrière-plan ce que les pages mettent du temps à calculer la première fois : la page qu'on
    ouvre ensuite n'attend plus (ou moins). Une erreur ici ne compte pas : la page la refera."""
    for step in (api.status, api.forge_collecte, lambda: api.forge_ranking("saved", None, None, None, None, False, None), api.ganymede_guides):
        try:
            step()
        except Exception as exc:  # noqa: BLE001
            log.info("Préparation en arrière-plan interrompue : %s", exc)

/**
 * Independent prime-owned worker families. Each active incarnation has its own maxWorkers
 * admission limit. Conversation identity resolves an owner; local names such as worker-1
 * never select an owner. Browser transactions additionally carry the exact incarnation ID.
 *
 * When a family's last worker stops, its full history parks under its prime conversation.
 * Waking that family creates a fresh incarnation without changing any worker conversation.
 * The continuation transaction alone can transfer the prime binding to another conversation.
 *
 * Spawn/message/finish plans cross the existing durable snapshot barrier before publication.
 * Every closure retains its exact owner/agent objects, so another owner's work cannot change
 * where a pending transaction commits or rolls back. Slots are admission, never eviction:
 * workers that prove they were still running remain recognized even above the current limit.
 */

import { randomUUID } from 'node:crypto';
import type { AgentInfo, AgentMessage, AgentState, ReasoningEffort, SwarmState } from '../shared/session.js';
import { REASONING_EFFORTS, isReasoningEffort } from '../shared/session.js';
import { getConfig } from './config.js';
import { liveConnectorName } from './mcp/surfaces.js';
import { workerBrief, workerOwnTask } from '../shared/worker-brief.js';
import { getChatModels, refreshForUnoffered } from './chat-models.js';
import { resolveChatModel, type ChatModelOption } from '../shared/chat-models.js';
import { logInfo, logWarn } from './logger.js';
import { inheritWorkspace, releasePrimeWorkspace, bindAgentWorkspace } from './workspace.js';
